examples.source:
actdiag {
  write -> read -> render;
  lane user {
    label = "User";
    write [label = "Write"];
  }
  lane server {
    label = "Server";
    read; render;
  }
}

actdiag {
  A -> B -> C;
  A -> C [label = "skip", style = dashed];
  lane x { A; }
  lane y { B [shape = flowchart.condition, label = "ok?"]; }
  lane z { C [shape = flowchart.database]; }
}

actdiag {
  span_height = 60;
  lane "front end" {
    color = "#DDEEFF";
    form; submit;
  }
  lane api {
    handler [label = "handle\nrequest"];
  }
  form -> submit -> handler;
}

actdiag {
  lane user { label = "User"; n0001 [label = "login"]; }
  lane srv { label = "Server"; n0002 [label = "check"]; n0003 [label = "reply"]; }
  n0001 -> n0002 -> n0003;
}
